+func newTrackerHarness(
+	t *testing.T,
+	node *unstructured.Unstructured,
+	pods ...*corev1.Pod,
+) *trackerHarness {
+	t.Helper()
+
+	kubeObjects := make([]k8sruntime.Object, 0, len(pods))
