+func TestNodeContainerState(t *testing.T) {
+	t.Parallel()
+
+	deleting := metav1.NewTime(time.Now())
+	pod := func(phase corev1.PodPhase, deleted bool) *corev1.Pod {
+		p := &corev1.Pod{Status: corev1.PodStatus{Phase: phase}}
